/// </summary>
class METAccountStatusUpdateController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// New.
/// </summary>
protected void new()
{
    super(classStr(METAccountStatusUpdateService), methodStr(METAccountStatusUpdateService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:AccountStatusUpdate";
}

/// <summary>
/// Starts the controller.
/// </summary>
/// <param name = "_args">Args.</param>
public static void main(Args _args)
{
    METAccountStatusUpdateController controller = new METAccountStatusUpdateController();

    controller.startOperation();
}
